mapper.sql:
WHERE hpr.status = 'open'
  AND hpr.tenant_id = #{tenantId}
  AND h.tenant_id = #{tenantId}

    AND (
        h.hostname LIKE CONCAT('%', #{keyword}, '%')
        OR h.ipv4 LIKE CONCAT('%', #{keyword}, '%')
        OR h.mac_address LIKE CONCAT('%', #{keyword}, '%')
        OR hpr.related_patch_id LIKE CONCAT('%', #{keyword}, '%')
        OR hpr.related_cve LIKE CONCAT('%', #{keyword}, '%')
    )


    AND LOWER(hpr.risk_level) = LOWER(#{riskLevel})


    AND hpr.risk_type = #{riskType}


    AND hps.pending_reboot = #{pendingReboot}


    AND h.os_name LIKE CONCAT('%', #{osName}, '%')

mapper.select:
SELECT DISTINCT host_id
FROM host_patch_status
WHERE tenant_id = #{tenantId}
